class ListNode:
    def __init__(self, val=0, nxt=None):
        self.val = val
        self.next = nxt


def build(vals):
    head = None
    for v in reversed(vals):
        head = ListNode(v, head)
    return head


def dump(head):
    out = []
    while head:
        out.append(head.val)
        head = head.next
    return out


def reverse(head):
    prev = None
    while head:
        nxt = head.next
        head.next = prev
        prev = head
        head = nxt
    return prev


def removeSmallerLeft(nums):
    head = reverse(build(nums))
    dummy = ListNode(0, head)
    prev, cur = dummy, head
    mx = None
    while cur:
        if mx is not None and cur.val < mx:
            prev.next = cur.next
        else:
            mx = cur.val
            prev = cur
        cur = cur.next
    return dump(reverse(dummy.next))
